import React, { useEffect, useState } from 'react';
import { useBalanceReportQuery } from '../../posApi';
import { appColors, brandColors, HEADER_GRADIENT } from '../../../theme/appColors';
import { Box, Button, CircularProgress, Paper, Stack, Typography } from '@mui/material';
import DownloadIcon from '@mui/icons-material/Download';
import PrintIcon from '@mui/icons-material/Print';
import AssessmentIcon from '@mui/icons-material/Assessment';

const PrintPage = () => {
  const { data, isLoading, isError } = useBalanceReportQuery();
  const [pdfBlob, setPdfBlob] = useState<Blob | null>(null);
  const [pdfUrl, setPdfUrl] = useState<string | null>(null);

  useEffect(() => {
    if (data) {
      setPdfBlob(data);
      setPdfUrl(URL.createObjectURL(data));
    }
  }, [data]);

  useEffect(() => {
    if (pdfUrl) {
      return () => URL.revokeObjectURL(pdfUrl);
    }
  }, [pdfUrl]);

  const downloadPdf = () => {
    if (!pdfBlob) return;
    const url = URL.createObjectURL(pdfBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'balanceReport.pdf';
    link.click();
  };

  const handlePrint = (blob: Blob) => {
    const url = URL.createObjectURL(blob);
    const iframe = document.createElement('iframe');
    iframe.style.display = 'none';
    iframe.src = url;
    iframe.onload = () => {
      iframe.contentWindow?.focus();
      iframe.contentWindow?.print();
      setTimeout(() => {
        URL.revokeObjectURL(url);
        document.body.removeChild(iframe);
      }, 1000);
    };
    document.body.appendChild(iframe);
  };

  return (
    <Box sx={{ backgroundColor: brandColors.contentBg, minHeight: '100%', p: { xs: 1.5, sm: 2 } }}>
      {/* Page Header */}
      <Paper
        elevation={0}
        sx={{ borderRadius: 2, mb: 2.5, overflow: 'hidden', boxShadow: '0 2px 12px rgba(15,29,77,0.12)' }}
      >
        <Box
          sx={{
            background: HEADER_GRADIENT,
            px: 3,
            py: 2,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            flexWrap: 'wrap',
            gap: 1,
          }}
        >
          <Stack direction="row" spacing={1.5} alignItems="center">
            <Box
              sx={{
                width: 38,
                height: 38,
                borderRadius: 1.5,
                backgroundColor: 'rgba(255,255,255,0.15)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              <AssessmentIcon sx={{ color: '#fff', fontSize: 22 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontWeight: 700, letterSpacing: 0.3 }} variant="h6">
                Balance Report
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.72)', fontSize: '0.78rem' }} variant="caption">
                Financial balance and account summary
              </Typography>
            </Box>
          </Stack>
          <Stack direction="row" spacing={1.5}>
            <Button
              disabled={isLoading || !pdfBlob}
              onClick={downloadPdf}
              startIcon={
                isLoading
                  ? <CircularProgress size={16} sx={{ color: '#fff' }} />
                  : <DownloadIcon />
              }
              sx={{
                backgroundColor: 'rgba(255,255,255,0.15)',
                color: '#fff',
                border: '1px solid rgba(255,255,255,0.35)',
                borderRadius: 1.5,
                px: 2,
                py: 0.75,
                fontWeight: 600,
                fontSize: '0.82rem',
                textTransform: 'none',
                '&:hover': { backgroundColor: 'rgba(255,255,255,0.25)' },
                '&:disabled': { color: 'rgba(255,255,255,0.45)', borderColor: 'rgba(255,255,255,0.2)' },
              }}
            >
              Download
            </Button>
            <Button
              disabled={isLoading || !pdfBlob}
              onClick={() => pdfBlob && handlePrint(pdfBlob)}
              startIcon={<PrintIcon />}
              sx={{
                backgroundColor: brandColors.teal,
                color: '#fff',
                border: 'none',
                borderRadius: 1.5,
                px: 2,
                py: 0.75,
                fontWeight: 600,
                fontSize: '0.82rem',
                textTransform: 'none',
                '&:hover': { backgroundColor: '#0a7375' },
                '&:disabled': { backgroundColor: 'rgba(15,139,141,0.5)', color: 'rgba(255,255,255,0.6)' },
              }}
            >
              Print
            </Button>
          </Stack>
        </Box>
      </Paper>

      {/* PDF Viewer */}
      <Paper
        elevation={0}
        sx={{ borderRadius: 2, overflow: 'hidden', boxShadow: '0 1px 8px rgba(0,0,0,0.07)', minHeight: 200 }}
      >
        {isLoading && (
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', py: 10 }}>
            <Stack spacing={2} alignItems="center">
              <CircularProgress size={36} sx={{ color: brandColors.teal }} />
              <Typography sx={{ color: '#6b7280', fontSize: '0.88rem' }}>Loading report...</Typography>
            </Stack>
          </Box>
        )}
        {isError && !isLoading && (
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              py: 10,
              gap: 1,
            }}
          >
            <AssessmentIcon sx={{ fontSize: 48, color: appColors.carmineRed[60] }} />
            <Typography sx={{ color: appColors.carmineRed[100], fontWeight: 600 }}>
              Failed to load report
            </Typography>
            <Typography sx={{ color: '#6b7280', fontSize: '0.84rem' }}>
              Please try refreshing the page
            </Typography>
          </Box>
        )}
        {pdfUrl && !isLoading && (
          <Box sx={{ display: 'flex', justifyContent: 'center', p: 2 }}>
            <iframe
              height="800px"
              src={`${pdfUrl}#toolbar=0`}
              style={{ border: 'none', borderRadius: 8 }}
              title="Balance Report PDF Preview"
              width="800px"
            />
          </Box>
        )}
      </Paper>
    </Box>
  );
};

export default PrintPage;
